        cr, cc = queue.pop(0)
        # Check all neighbors going up or sideways
        for dr, dc in [(-1,0),(0,-1),(0,1),(1,0)]:
            nr, nc = cr+dr, cc+dc
            if 0 <= nr < h and 0 <= nc < w and test_input[nr][nc] == 2:
